import{_ as t,r as a,o as c,c as o,e as n,a as l,s as r}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"哈希与加密 - October CMS - 2.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"配置","slug":"配置","link":"#配置","children":[]},{"level":2,"title":"哈希(Hash)","slug":"哈希-hash","link":"#哈希-hash","children":[{"level":4,"title":"根据哈希验证密码","slug":"根据哈希验证密码","link":"#根据哈希验证密码","children":[]},{"level":4,"title":"检查密码是否需要重新生成哈希","slug":"检查密码是否需要重新生成哈希","link":"#检查密码是否需要重新生成哈希","children":[]}]},{"level":2,"title":"加密","slug":"加密","link":"#加密","children":[{"level":4,"title":"解密一个值","slug":"解密一个值","link":"#解密一个值","children":[]}]}],"relativePath":"2.x/zh-cn/services/hashing-encryption.md","filePath":"2.x/zh-cn/services/hashing-encryption.md"}'),i={name:"2.x/zh-cn/services/hashing-encryption.md"};function u(k,s,d,h,g,m){const e=a("pre-heading"),p=a("post-heading");return c(),o("div",null,[n(e),s[0]||(s[0]=l("h1",null,"哈希与加密",-1)),n(p),s[1]||(s[1]=r(`<h2 id="配置"><a href="#配置" class="header-anchor">#</a> 配置</h2><p>当您第一次安装October时，应该已经为您生成了一个随机密钥。 您可以通过检查 <code>config/app.php</code> 配置文件的 <code>key</code> 选项来确认这一点。 如果密钥保持不变，则应将其设置为 32 个字符的随机字符串。 如果未正确设置此值，则所有加密值都将是不安全的。</p><h2 id="哈希-hash"><a href="#哈希-hash" class="header-anchor">#</a> 哈希(Hash)</h2><p><code>Hash</code> 门面为存储用户密码提供了安全的 Bcrypt 哈希。 Bcrypt 是哈希密码的绝佳选择，因为它的&quot;装填因子&quot;是可调整的，这意味着生成哈希所需的时间可以随着硬件功率的增加而增加。</p><p>您可以通过调用 <code>Hash</code> 门面上的 <code>make</code> 方法来设置哈希密码：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">User</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">password</span> <span class="token operator">=</span> <span class="token class-name static-context">Hash</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;mypassword&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>或者，模型可以实现 <a href="./../database/traits.html#oc-hashable">哈希特征</a> 来自动设置哈希属性。</p><h4 id="根据哈希验证密码"><a href="#根据哈希验证密码" class="header-anchor">#</a> 根据哈希验证密码</h4><p><code>check</code> 方法允许您验证给定的纯文本字符串是否对应于给定的哈希。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">Hash</span><span class="token operator">::</span><span class="token function">check</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;plain-text&#39;</span><span class="token punctuation">,</span> <span class="token variable">$hashedPassword</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// 密码匹配...</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="检查密码是否需要重新生成哈希"><a href="#检查密码是否需要重新生成哈希" class="header-anchor">#</a> 检查密码是否需要重新生成哈希</h4><p><code>needsRehash</code> 函数允许您确定哈希器使用的装填因子是否在密码被哈希后发生了变化：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">Hash</span><span class="token operator">::</span><span class="token function">needsRehash</span><span class="token punctuation">(</span><span class="token variable">$hashed</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$hashed</span> <span class="token operator">=</span> <span class="token class-name static-context">Hash</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;plain-text&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="加密"><a href="#加密" class="header-anchor">#</a> 加密</h2><p>你可以使用 <code>Crypt</code> 门面加密一个值。 所有加密值都使用 OpenSSL 和<code>AES-256-CBC</code>密码进行加密。 此外，所有加密值都使用消息验证码(MAC)进行签名，以检测对加密字符串的任何修改。</p><p>例如，我们可以使用 <code>encrypt</code> 方法加密一个密文并将其存储在 <a href="./../database/model.html">数据库模型</a> 中：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">User</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">secret</span> <span class="token operator">=</span> <span class="token class-name static-context">Crypt</span><span class="token operator">::</span><span class="token function">encrypt</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;我在村东头老槐树下藏了一箱黄金&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="解密一个值"><a href="#解密一个值" class="header-anchor">#</a> 解密一个值</h4><p>当然，您可以使用 <code>Crypt</code> 门面上的 <code>decrypt</code> 方法解密值。 如果无法正确解密该值，例如 MAC 无效，则会抛出 <code>Illuminate\\Contracts\\Encryption\\DecryptException</code> 异常：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">use</span> <span class="token package">Illuminate<span class="token punctuation">\\</span>Contracts<span class="token punctuation">\\</span>Encryption<span class="token punctuation">\\</span>DecryptException</span><span class="token punctuation">;</span>

<span class="token keyword">try</span> <span class="token punctuation">{</span>
    <span class="token variable">$decrypted</span> <span class="token operator">=</span> <span class="token class-name static-context">Crypt</span><span class="token operator">::</span><span class="token function">decrypt</span><span class="token punctuation">(</span><span class="token variable">$encryptedValue</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token keyword">catch</span> <span class="token punctuation">(</span><span class="token class-name">DecryptException</span> <span class="token variable">$ex</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span>
</code></pre></div><p>或者，模型可以实现 <a href="./../database/traits.html#oc-encryptable">加密 特征</a> 来自动加密和解密属性。</p>`,21))])}const f=t(i,[["render",u]]);export{y as __pageData,f as default};
